package com.example.solarfarm.domain;

import jakarta.persistence.*; import java.time.Instant; import com.example.solarfarm.domain.Enums.AlertStatus;
@Entity @Table(name="alerts") public class Alert { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="panel_id") private Panel panel; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="prediction_id") private Prediction prediction; @Column(name="fault_type",nullable=false) private String faultType; @Column(nullable=false) private String severity; @Column(nullable=false) private String message; @Enumerated(EnumType.STRING) @Column(nullable=false) private AlertStatus status=AlertStatus.OPEN; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="acknowledged_at") private Instant acknowledgedAt; protected Alert(){} public Alert(Panel p,Prediction pr,String f,String s,String m){panel=p;prediction=pr;faultType=f;severity=s;message=m;} public Long getId(){return id;} public Panel getPanel(){return panel;} public Prediction getPrediction(){return prediction;} public String getFaultType(){return faultType;} public String getSeverity(){return severity;} public String getMessage(){return message;} public AlertStatus getStatus(){return status;} public void acknowledge(){status=AlertStatus.ACKNOWLEDGED;acknowledgedAt=Instant.now();} }
